mapper.select:
select a.INDENTIFY_MARK, a.ORG_INDENTIFY_MARK, a.REGIST_BANK_CODE, a.IS_BELONG_BANK, a.THE_BANK_NAME, a.THE_BANK_CODE, a.HOLDER_MARK, a.HOLDER_REGION, a.HOLDER_TYPE, a.PERSONAL_IDENTIFY_TYPE, a.INSTITUTION_IDENTIFY_TYPE, a.OTHER_IDENTIFY_NAME, a.IDENTIFY_NUMBER, a.SPV_CAP_ACC_BANK, a.OTHER_CAP_ACC_BANK, a.SPV_REGIST_CODE, a.HOLDER_DATE, a.HOLDER_NAME, a.HOLDER_SEX, a.HOLDER_RISK_PREFER, a.HOLDER_CELLPHONE, a.HOLDER_TELEPHONE, a.IS_SUBMIT, a.HOLDER_EMAIL, a.REMARK, a.STATUS, a.WORKFLOW_ID, a.DEPT_CODE, a.UPDATE_USER, a.UPDATE_TIME, a.CREATE_USER, a.CREATE_TIME,a.DATA_DATE, a.DATA_SOURCE, a.ORG_CODE, a.AGENT, a.CREATE_DEPT, a.INTERF_CHECK_RESULT,a.OPERATE_STATUS,a.MERGER_INDENTIFY_MARK, IM.IMARK,sub.INDENTIFY_MARK isOrNoSubmit from CHB_EQU_HOLD_CHECK a left join chb_equ_sub sub on sub.INDENTIFY_MARK=a.MERGER_INDENTIFY_MARK and sub.SUBMIT_STATUS in ('02','03') left join ( SELECT INDENTIFY_MARK IMARK, HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER, rank() over( partition by HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER order by INDENTIFY_MARK desc) ineerrank FROM CHB_EQU_HOLD_CHECK ) IM ON a.HOLDER_NAME=IM.HOLDER_NAME AND ifnull(a.PERSONAL_IDENTIFY_TYPE,a.INSTITUTION_IDENTIFY_TYPE)=ifnull(IM.PERSONAL_IDENTIFY_TYPE,IM.INSTITUTION_IDENTIFY_TYPE) and ifnull(a.OTHER_IDENTIFY_NAME,1)=ifnull(IM.OTHER_IDENTIFY_NAME,1) and a.IDENTIFY_NUMBER=IM.IDENTIFY_NUMBER AND IM.INEERRANK = 1 where 1=1
and a.MERGER_INDENTIFY_MARK like concat_ws('','%', #{mergerIndentifyMark,jdbcType=VARCHAR},'%')
and a.IDENTIFY_NUMBER like concat_ws('','%', #{identifyNumber,jdbcType=VARCHAR},'%')
and a.HOLDER_NAME like concat_ws('','%', #{holderName,jdbcType=VARCHAR},'%')
#{items,jdbcType=VARCHAR}
and DATE_FORMAT(a.DATA_DATE,'%Y-%m-%d') >= #{dataTimeStart,jdbcType=VARCHAR}
and DATE_FORMAT(a.DATA_DATE,'%Y-%m-%d') <= #{dataTimeEnd,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
#{items,jdbcType=VARCHAR}
order by (CASE WHEN a.INSTITUTION_IDENTIFY_TYPE IS NULL then 'A' else 'B' end) desc,IMARK desc,a.INDENTIFY_MARK desc

select from CHB_EQU_HOLD_CHECK where 1=1 AND OPERATE_STATUS = '01'
AND concat_ws('',REGIST_BANK_CODE, '_', IDENTIFY_NUMBER, '_',HOLDER_NAME, '_', PERSONAL_IDENTIFY_TYPE, '_', INSTITUTION_IDENTIFY_TYPE, '_', OTHER_IDENTIFY_NAME) IN
#{key,jdbcType=VARCHAR}

select a.INDENTIFY_MARK, a.ORG_INDENTIFY_MARK, a.REGIST_BANK_CODE, a.IS_BELONG_BANK, a.THE_BANK_NAME, a.THE_BANK_CODE, a.HOLDER_MARK, a.HOLDER_REGION, a.HOLDER_TYPE, a.PERSONAL_IDENTIFY_TYPE, a.INSTITUTION_IDENTIFY_TYPE, a.OTHER_IDENTIFY_NAME, a.IDENTIFY_NUMBER, a.SPV_CAP_ACC_BANK, a.OTHER_CAP_ACC_BANK, a.SPV_REGIST_CODE, a.HOLDER_DATE, a.HOLDER_NAME, a.HOLDER_SEX, a.HOLDER_RISK_PREFER, a.HOLDER_CELLPHONE, a.HOLDER_TELEPHONE, a.IS_SUBMIT, a.HOLDER_EMAIL, a.REMARK, a.STATUS, a.WORKFLOW_ID, a.DEPT_CODE, a.UPDATE_USER, a.UPDATE_TIME, a.CREATE_USER, a.CREATE_TIME,a.DATA_DATE, a.DATA_SOURCE, a.ORG_CODE, a.AGENT, a.CREATE_DEPT, a.INTERF_CHECK_RESULT,a.OPERATE_STATUS,a.MERGER_INDENTIFY_MARK, IM.IMARK from CHB_EQU_HOLD_CHECK a left join ( SELECT INDENTIFY_MARK IMARK, HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER, rank() over( partition by HOLDER_NAME,PERSONAL_IDENTIFY_TYPE,INSTITUTION_IDENTIFY_TYPE,OTHER_IDENTIFY_NAME,IDENTIFY_NUMBER order by INDENTIFY_MARK desc) ineerrank FROM CHB_EQU_HOLD_CHECK ) IM ON a.HOLDER_NAME=IM.HOLDER_NAME AND ifnull(a.PERSONAL_IDENTIFY_TYPE,a.INSTITUTION_IDENTIFY_TYPE)=ifnull(IM.PERSONAL_IDENTIFY_TYPE,IM.INSTITUTION_IDENTIFY_TYPE) and ifnull(a.OTHER_IDENTIFY_NAME,1)=ifnull(IM.OTHER_IDENTIFY_NAME,1) and a.IDENTIFY_NUMBER=IM.IDENTIFY_NUMBER AND IM.INEERRANK = 1 where 1=1
#{items.indentifyMark,jdbcType=VARCHAR}
order by (CASE WHEN a.INSTITUTION_IDENTIFY_TYPE IS NULL then 'A' else 'B' end) desc,IMARK desc,a.INDENTIFY_MARK desc

