mapper.update:
update CHB_EQU_HOLD_CHECK
set MERGER_INDENTIFY_MARK =
#{mergerindentifymark,jdbcType=VARCHAR},
OPERATE_STATUS =
#{operatestatus,jdbcType=VARCHAR},
UPDATE_TIME = NOW()

	,UPDATE_USER = #{updateUser,jdbcType=VARCHAR}

where HOLDER_NAME=#{holderName,jdbcType=VARCHAR}

	and PERSONAL_IDENTIFY_TYPE=#{personalIdentifyType,jdbcType=CHAR}


	and
	INSTITUTION_IDENTIFY_TYPE=#{institutionIdentifyType,jdbcType=VARCHAR}


	and OTHER_IDENTIFY_NAME=#{otherIdentifyName,jdbcType=VARCHAR}

and IDENTIFY_NUMBER=#{identifyNumber,jdbcType=VARCHAR}

choose.when:
begin
UPDATE CHB_EQU_HOLD_CHECK HOLDCHECK SET HOLDCHECK.ORG_INDENTIFY_MARK = #{item.orgIndentifyMark,jdbcType=VARCHAR}, HOLDCHECK.INDENTIFY_MARK = #{item.indentifyMark,jdbcType=VARCHAR}, HOLDCHECK.UPDATE_TIME = NOW() WHERE HOLDCHECK.INDENTIFY_MARK = HOLDCHECK.MERGER_INDENTIFY_MARK AND HOLDCHECK.MERGER_INDENTIFY_MARK = #{item.orgIndentifyMark,jdbcType=VARCHAR};
UPDATE CHB_EQU_HOLD_CHECK HOLDCHECK SET HOLDCHECK.MERGER_INDENTIFY_MARK = #{item.indentifyMark,jdbcType=VARCHAR}, HOLDCHECK.UPDATE_TIME = NOW() WHERE HOLDCHECK.MERGER_INDENTIFY_MARK = #{item.orgIndentifyMark,jdbcType=VARCHAR}
;end;

BEGIN
UPDATE CHB_PRD_DEAL DEAL SET DEAL.INDENTIFY_MARK = (SELECT T.MERGER_INDENTIFY_MARK FROM CHB_EQU_HOLD_CHECK T WHERE T.INDENTIFY_MARK = DEAL.INDENTIFY_MARK ), DEAL.UPDATE_TIME = NOW() WHERE EXISTS (SELECT 1 FROM CHB_EQU_HOLD_CHECK T WHERE T.INDENTIFY_MARK = DEAL.INDENTIFY_MARK AND T.MERGER_INDENTIFY_MARK IS NOT NULL AND concat_ws('', T.REGIST_BANK_CODE, '_', T.IDENTIFY_NUMBER, '_',T.HOLDER_NAME, '_', T.PERSONAL_IDENTIFY_TYPE, '_', T.INSTITUTION_IDENTIFY_TYPE, '_', T.OTHER_IDENTIFY_NAME) = concat_ws('', ifnull(#{item.bankCode,jdbcType=VARCHAR},''), '_', ifnull(#{item.identifyNumber,jdbcType=VARCHAR},''), '_', ifnull(#{item.holderName,jdbcType=VARCHAR},''), '_', ifnull(#{item.personalIdentifyType,jdbcType=VARCHAR},''), '_', ifnull(#{item.institutionIdentifyType,jdbcType=VARCHAR},''), '_', ifnull(#{item.otherIdentifyName,jdbcType=VARCHAR},'')) );
UPDATE CHB_PRD_POSITION POS SET POS.INDENTIFY_MARK =(SELECT T.MERGER_INDENTIFY_MARK FROM CHB_EQU_HOLD_CHECK T WHERE T.INDENTIFY_MARK = POS.INDENTIFY_MARK ) WHERE EXISTS (SELECT 1 FROM CHB_EQU_HOLD_CHECK T WHERE T.INDENTIFY_MARK = POS.INDENTIFY_MARK AND T.MERGER_INDENTIFY_MARK IS NOT NULL AND concat_ws('', T.REGIST_BANK_CODE, '_', T.IDENTIFY_NUMBER, '_',T.HOLDER_NAME, '_', T.PERSONAL_IDENTIFY_TYPE, '_', T.INSTITUTION_IDENTIFY_TYPE, '_', T.OTHER_IDENTIFY_NAME) = concat_ws('', ifnull(#{item.bankCode,jdbcType=VARCHAR},''), '_', ifnull(#{item.identifyNumber,jdbcType=VARCHAR},''), '_', ifnull(#{item.holderName,jdbcType=VARCHAR},''), '_', ifnull(#{item.personalIdentifyType,jdbcType=VARCHAR},''), '_', ifnull(#{item.institutionIdentifyType,jdbcType=VARCHAR},''), '_', ifnull(#{item.otherIdentifyName,jdbcType=VARCHAR},'')) )
;END;
